<!-- Hint - individual bottom bar item -->
<template>
  <BngButton
    v-show="bindingDisplayed"
    class="hint"
    :class="{ 'flash-on': data.flash }"
    :accent="ACCENTS.text"
    :disabled="!data.action"
    @click="data.action"
  >
    <div class="hint-content">
      <div class="binding-container" v-if="bindingView.length > 0">
        <template v-for="(item, idx) in bindingView" :key="idx">
          <span class="rich">
            <span v-if="item.type === 'icon'" class="icon">
              <BngIcon v-bind="{ ...PROP_DEFAULTS[item.type], ...item.props }" />
            </span>
            <BngBinding
              ref="bindingRefs"
              class="binding"
              v-bind="{ ...PROP_DEFAULTS[item.type], ...item.props }"
              track-ignore
            />
            <span v-if="item.hold" class="text">{{ item.hold ? "[hold]" : "" }}</span>
          </span>
        </template>
      </div>
      <template v-if="labelView">
        <span class="hint-text">
          {{ $tt(labelView) }}
        </span>
      </template>
    </div>
  </BngButton>
</template>

<script setup>
import { ref, computed } from "vue"
import { BngBinding, BngIcon, BngButton, ACCENTS } from "@/common/components/base"

const props = defineProps({
  data: Object,
})

const PROP_DEFAULTS = {
  icon: { color: "white" },
  binding: {
    showUnassigned: true,
    dark: false,
  },
}

const hintContent = computed(() => {
  const hints = (props.data ? [props.data.content].flat() : [])
  const res = []
  let label
  for (const hint of hints) {
    if (typeof hint === "string") {
      label = hint
    } else {
      if (hint.label) label = hint.label
      res.push({
        ...hint,
        label: undefined,
      })
    }
  }
  label && res.push(label)
  return res
})

const bindingView = computed(() => hintContent.value.filter(item => typeof item !== "string"))
const labelView = computed(() => hintContent.value.find(item => typeof item === "string") || bindingView.value.find(item => item.label)?.label)

const bindingRefs = ref([])
const bindingDisplayed = computed(() => bindingRefs.value.some(ref => ref.displayed))

/*
// Expected Hint Structure
{
  id: String,  // id for the hint
  content: Object/String/Array  // Object (icon or binding) or String (simple label) or Array (array of Objects and/or Strings to allow combinations of icons, bindings, labels),
  action: Function,
  [bngClickOpts: Object]  // Optional - for dealing with long press stuff. Don't worry about this yet - it's low priority and more of a "nice to have"
}

// Icon Object
{
  type: 'icon',
  [props: Object],  // props that would normally be passed to a BngIcon
  [label: String], // optional label
}

// Binding Object
{
  type: 'binding',
  [props: Object],  // props that would normally be passed to a BngBinding
  [label: String], // optional label
  [hold: Boolean]  // optional - will display a 'HOLD' message alongside binding if True
}
*/
</script>

<style lang="scss" scoped>
.hint {
  margin: 0 !important;
  padding-top: 0;
  padding-bottom: 0;
  min-width: none;
  height: 100%;
  display: flex;
  align-items: center;
  flex-direction: column;

  opacity: 1 !important;
  &:not(:hover):deep(.background) {
    background-color: transparent !important;
    transition: background-color 0s ease-out;
  }

  .binding-container {
    display: flex;
    flex-flow: row nowrap;
  }

  .hint-content {
    display: flex;
    align-items: center;
    flex-flow: row nowrap;
    gap: 0.25em;
    max-width: 100%;
    .hint-text {
      white-space: nowrap;
      text-overflow: ellipsis;
      flex: 1 auto;
      overflow: hidden;
    }

    @media (max-width: 940px) {
      flex-direction: column;
      font-size: 0.8em;
      line-height: 1;
    }
  }

  // this will appear only when icon is shown
  .rich {
    display: inline-block;

    .icon > * {
      height: 1em;
      margin-right: 0.2em;
    }
    .binding {
      height: 1em;
      margin-right: 0.1em;
      padding-right: 0;
    }
    .text {
    }
  }

  :deep(.flash-on) {
    .icon-base,
    .icon-base + span {
      // color:#fc0 !important;
      animation: flash 1s ease-out 0s 2 forwards !important;
      @keyframes flash {
        0%, 100% {
          color: inherit;
        }
        15%, 50% {
          color: var(--bng-orange-400);
        }
      }
    }
  }
}
</style>
