<script setup>

import { LayoutSingle } from "@/common/layouts"
import { BngButton, ACCENTS, BngScreenHeading, BngProgressBar, BngIcon, icons, BngBinding, BngCardHeading } from "@/common/components/base"
import { vBngBlur, vBngOnUiNav, vBngSoundClass } from "@/common/directives"
import MissionCard from "../components/progress/MissionCard.vue"
import LeagueRow from "../components/progress/LeagueRow.vue"
import { CareerStatus } from "@/modules/career/components"
import DeliveryFacilityCard from "../components/progress/DeliveryFacilityCard.vue"
import { lua } from "@/bridge"
import { ref, computed, onMounted } from "vue"
import { useUINavScope } from "@/services/uiNav"
import UnlockProgressBar from "../components/progress/UnlockProgressBar.vue"
import { $translate } from "@/services/translation"
import BranchSkillProgressBar from "../components/progress/BranchSkillProgressBar.vue"
import { getBranchColorStyle, getIconBackgroundStyle } from "@/utils/colorUtils"
import Organizations from "../components/organizations/Organizations.vue"
useUINavScope("branch") // UI Nav events to fire from (or from focused element inside) element with attribute: bng-ui-scope="branch"
import router from "@/router"
const props = defineProps({
  branchKey: String,
  skillKey: String,
})

const page = ref({})

const BRANCHES_UNIT_TYPES = {
  labourer: "deliveryTruckArrows",
  specialized: "carChase01",
  motorsport: "raceFlag",
  adventurer: "jump",
}

const missions = ref([])
const facilities = ref([])
const leagues = ref([])
const skills = ref([])
const deliveryProgressSkills = ref([])
const skillDescription = ref()
const selectedFilter = ref('all')
const skillBars = ref([])

async function filterChanged(filter) {
  if (Array.isArray(page.value.missions)) {
    missions.value = page.value.missions.filter(itm => !itm.locked && itm.skill[0] === filter)
  }
  if (Array.isArray(page.value.facilities)) {
    facilities.value = page.value.facilities.filter(itm => !itm.locked && (itm.skill[0] && itm.skill.some(skill => skill == filter)))
    facilities.value.sort((a,b) => {
      if(a.visible === b.visible)
        return a.name < b.name
      else
        return a.visible ? -1 : 1
    })
  }
  if(Array.isArray(page.value.leagues)) {
    leagues.value = page.value.leagues.filter(itm => itm.skillId == filter)
  }

  skills.value = page.value.details.skills
  if (filter === page.value.skillInfo.id) {
    skillDescription.value = page.value.details.description
  } else {
    skillDescription.value = page.value.details.skills.find(e => e.id == filter).description
  }
}

function setFilter(filter) {
  selectedFilter.value = filter
  filterChanged(filter)
}

function focusPreviousFilter() {
  const currentIndex = skills.value.findIndex(skill => skill.id === selectedFilter.value)
  if (selectedFilter.value === page.value.skillInfo.id) {
    setFilter(skills.value[skills.value.length - 1].id)
  } else if (currentIndex > 0) {
    setFilter(skills.value[currentIndex - 1].id)
  } else {
    setFilter(page.value.skillInfo.id)
  }
}

function focusNextFilter() {
  const currentIndex = skills.value.findIndex(skill => skill.id === selectedFilter.value)
  if (selectedFilter.value === page.value.skillInfo.id) {
    setFilter(skills.value[0].id)
  } else if (currentIndex < skills.value.length - 1) {
    setFilter(skills.value[currentIndex + 1].id)
  } else {
    setFilter(page.value.skillInfo.id)
  }
}

async function setup(data) {
  page.value = data
  if(props.skillKey) {
    setFilter(props.skillKey)
  } else {
    setFilter(data.skillInfo.id)
  }
}

const leagueMissionClicked = mission => {
  if (mission.canStartFromProgressScreen) {
    lua.extensions.gameplay_missions_missionScreen.setPreselectedMissionId(mission.id)
    lua.extensions.gameplay_missions_missionScreen.openAPMChallenges(props.branchKey, mission.skill[0])
  } else {
    lua.extensions.gameplay_missions_missionScreen.navigateToMission(mission.id)
  }
}

function playChallenges() {
  lua.extensions.gameplay_missions_missionScreen.openAPMChallenges(props.branchKey, selectedFilter.value)
}

onMounted(async () => {
  console.log(props.branchKey)
  setup(await lua.career_modules_branches_landing.getBranchPageData(props.branchKey))
})

const exit = () => {
  router.back()
}

const branchStyle = computed(() => {
  if (!page.value.details) {
    return {}
  }

  return getBranchColorStyle({
    color: page.value.details.color,
    accentColor: page.value.details.accentColor
  })
})

const headingText = computed(() => {
  if(!page.value.details) {
    return ""
  }
  return `${$translate.instant(page.value.details.name)}`
})

const currentSkillToShow = computed(() => {
  if (!page.value.details) return null

  if (selectedFilter.value === page.value.skillInfo.id) {
    return page.value.skillInfo
  }

  const selectedSkill = skills.value.find(skill =>
    skill.id === selectedFilter.value
  )

  return selectedSkill || page.value.skillInfo
})

const skillIconType = computed(() => {
  if (!page.value.skillInfo) return icons.lockClosed
  if (page.value.skillInfo.isInDevelopment) {
    return icons.roadblockL
  }
  if (page.value.skillInfo.unlocked) {
    return icons[page.value.skillInfo.icon]
  }
  return icons.lockClosed
})

function getSkillIconType(skill) {
  if (skill.isInDevelopment) {
    return icons.roadblockL
  }
  return icons[skill.unlocked ? skill.icon : 'lockClosed']
}
</script>

