<template>
  <div class="gameplay-apps">
    <component class="app" v-if="app" :is="app" v-bind="$attrs"/>

    <countdown class="countdown" v-if="true"/>
    <simpleFlashMessage class="flash-message" v-if="true"/>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted, computed, markRaw } from 'vue'
import { rallyVisualPacenotes, driftCurrentDrift, dragRaceTree, countdown, simpleFlashMessage, pointsBar } from '@/modules/apps'
import { useEvents } from '@/services/events'
import { useBridge } from '@/bridge'
const { lua } = useBridge()

const events = useEvents()

const isDrift = ref(false)
const isDragStaging = ref(false)
const isRally = ref(false)
const isPointsBar = ref(false)

const app = computed(() => {
  if (isRally.value) {
    return markRaw(rallyVisualPacenotes)
  }
  else if (isDrift.value) {
    return markRaw(driftCurrentDrift)
  }
  if (isDragStaging.value) {
    return markRaw(dragRaceTree)
  }
  if (isPointsBar.value) {
    return markRaw(pointsBar)
  }
})

const setContext = (context) => {
  //console.log('setContext', context)
  isRally.value = context === 'rally'
  isDrift.value = context === 'drift'
  isDragStaging.value = context === 'drag'
  isPointsBar.value = context === 'pointsBar'
}

onMounted(() => {
  events.on('setGameplayAppContext', (data) => setContext(data.context))
  lua.ui_gameplayAppContainers.getContainerContext('gameplayApps').then(setContext)
})
onUnmounted(() => {
  events.off('setGameplayAppContext', setContext)
})

</script>

<style lang="scss" scoped>
.gameplay-apps {
  display: flex;
  align-items: stretch;
  flex-direction: column;
  width: 100%;
  height: 100%;
  >* {
    flex: 1 0 auto;
  }
}
</style>
