<template>
  <div class="bng-path">
    <template v-for="(item, index) in pathView" :key="index">
      <BngButton v-if="!item.dropdown" class="bng-path-item" :accent="ACCENTS.text" v-bng-blur="blur" @click="onClick(item)">
        {{ item.label }}
      </BngButton>
      <template v-else>
        <BngButton class="bng-path-item bng-path-has-dropdown"
          :accent="ACCENTS.text" :icon="icons.arrowSmallRight" v-bng-blur="blur"
          v-bng-popover:bottom-start.click="item.dropdown"
        />
        <BngPopoverMenu :name="item.dropdown" focus>
          <template #default="{ hide }">
            <BngButton
              v-for="(subitem, idx) in item.items"
              :key="idx"
              :class="{ selected: idx === item.selected }"
              :accent="ACCENTS.menu"
              v-bng-on-ui-nav:ok.focusRequired.asMouse
              @click="onClick(subitem, hide)">
              {{ subitem.label }}
            </BngButton>
          </template>
        </BngPopoverMenu>
      </template>
    </template>
  </div>
</template>

<script setup>
import { computed } from "vue"
import { BngButton, BngPopoverMenu, ACCENTS, icons } from "@/common/components/base"
import { vBngBlur, vBngPopover, vBngOnUiNav } from "@/common/directives"

const emit = defineEmits(["click"])

const props = defineProps({
  items: Array,
  limit: {
    // how many items to display in path
    type: [Number, String],
    default: 3,
    validator: val => Number(val) > 0,
  },
  simple: Boolean, // disables arrows
  blur: Boolean,
})

const pathView = computed(() => {
  // if defined
  if (!Array.isArray(props.items)) return []

  const mapItem = itm => ({ label: itm.label, items: itm.items, data: itm })

  const items = props.items.map(mapItem)

  // apply limit of displayed items
  const res = props.limit ? items.slice(-props.limit) : items

  // add arrows
  if (!props.simple) {
    const looseCmp = (a, b) => a.label === b.label && a.value === b.value
    const len = res.length
    for (let i = 1; i < len; i++) {
      const idx = len - i
      const items = Array.isArray(res[idx - 1].items) ? res[idx - 1].items : [res[idx].data]
      res.splice(idx, 0, {
        dropdown: `bng-path-sub-${idx}`,
        selected: items.findIndex(itm => looseCmp(itm, res[idx])),
        items: items.map(mapItem),
      })
    }
  }

  // add overflown item
  if (props.limit && items.length > props.limit) {
    res.unshift({
      label: "…",
      data: items[items.length - props.limit - 1],
    })
  }

  return res
})

function onClick(item, popClose) {
  typeof popClose === "function" && popClose()
  emit("click", item.data)
}
</script>

<style lang="scss" scoped>
@import "@/styles/modules/mixins";

$corners: var(--bng-corners-1);

.bng-path {
  display: inline-flex;
  flex-flow: row nowrap;
  justify-content: flex-start;
  > .bng-path-item {
    flex: 0 0 auto;
    margin-left: 0 !important;
    margin-right: 0 !important;
    min-width: unset !important;
    &:not(.bng-path-has-dropdown) {
      padding-left: 0.75em;
      padding-right: 0.75em;
      :deep(.label) {
        max-width: 10em;
        font-style: italic;
        white-space: nowrap;
        text-overflow: ellipsis;
      }
    }
    &.bng-path-has-dropdown {
      padding-left: 0;
      padding-right: 0.15em;
    }
    border-radius: 0;
    &:first-child {
      border-radius: $corners 0 0 $corners;
    }
    &:last-child {
      border-radius: 0 $corners $corners 0;
    }
    @include modify-focus($border-rad-1, 0.0rem);
    &.bng-path-disabled {
      pointer-events: none;
    }
  }
}
</style>
