<template>
  <div
    ref="bngOverflowContainer"
    class="bng-overflow-container"
    @wheel="onWheel"
  >
    <div
      v-show="showLeftFade"
      class="fade-left"
      @mouseenter="startScrolling('left')"
      @mouseleave="stopScrolling"
    ></div>
    <div
      v-show="showRightFade"
      class="fade-right"
      @mouseenter="startScrolling('right')"
      @mouseleave="stopScrolling"
    ></div>
    <div class="scroll-container" ref="scrollContainer" @scroll="onScroll">
      <slot></slot>
    </div>
  </div>
</template>

<script setup>
import { ref, watch, onUnmounted } from "vue"

const props = defineProps({
  scrollSpeed: {
    type: Number,
    default: 5,
  },
})

defineExpose({
  scrollToLeft: () => scrollContainer.value.scrollTo({ left: 0, behavior: "smooth" }),
  scrollToRight: () => scrollContainer.value.scrollTo({ left: scrollContainer.value.scrollWidth, behavior: "smooth" }),
  scrollBy: amount => scrollContainer.value.scrollBy({ left: amount, behavior: "smooth" }),
})

const emit = defineEmits(["scroll"])

function notify() {
  emit("scroll", {
    scrollLeft: scrollContainer.value.scrollLeft,
    scrollWidth: scrollContainer.value.scrollWidth,
    clientWidth: scrollContainer.value.clientWidth,
  })
}

const bngOverflowContainer = ref(null)
const scrollContainer = ref(null)
const showLeftFade = ref(false)
const showRightFade = ref(false)
const resizeObserver = new ResizeObserver(updateFadeVisibility)
let scrollInterval = null

watch(scrollContainer, elm => {
  if (elm) {
    updateFadeVisibility()
    resizeObserver.observe(elm)
  }
}, { immediate: true })

function updateFadeVisibility() {
  if (!scrollContainer.value) return
  const { scrollLeft, scrollWidth, clientWidth } = scrollContainer.value
  showLeftFade.value = scrollLeft > 0
  showRightFade.value = scrollLeft < (scrollWidth - clientWidth)
}

function startScrolling(direction) {
  stopScrolling()
  scrollInterval = setInterval(() => {
    const scrollAmount = direction === "left" ? -props.scrollSpeed : props.scrollSpeed
    scrollContainer.value.scrollLeft += scrollAmount
    updateFadeVisibility()
    notify()
  }, 1000 / 30) // 1000ms / fps
}

function stopScrolling() {
  if (scrollInterval) {
    clearInterval(scrollInterval)
    scrollInterval = null
  }
}

function onWheel(evt) {
  evt.preventDefault()
  scrollContainer.value.scrollLeft += evt.deltaY
  updateFadeVisibility()
  notify()
}

function onScroll() {
  updateFadeVisibility()
  notify()
}

onUnmounted(() => {
  stopScrolling()
  resizeObserver.disconnect()
})
</script>

<style scoped lang="scss">
@import "@/styles/modules/mixins";

* {
  box-sizing: border-box;
}

.bng-overflow-container {
  position: relative;
  background-color: rgba(0, 0, 0, 0.5);
  border-radius: $border-rad-2;
  max-width: 40em;
  overflow: hidden;
}

.scroll-container {
  display: flex;
  flex-flow: row nowrap;
  // gap: 0.5em;
  padding: 0.25em;
  overflow-x: auto;
  overflow-y: hidden;
  z-index: 0;
  &::-webkit-scrollbar {
    display: none;
  }
}

.fade-left,
.fade-right {
  content: "";
  position: absolute;
  display: block;
  top: 0;
  width: 2em;
  height: 100%;
  background-image: linear-gradient(90deg, rgba(0, 0, 0, 0.65), #0000);
  cursor: pointer;
  z-index: 2;
  &:hover {
    background-image: linear-gradient(90deg, rgba(var(--bng-orange-700-rgb), 0.8), #0000);
  }
}
.fade-left {
  left: 0;
}
.fade-right {
  right: 0;
  transform: scaleX(-1);
}
</style>
