<template>
  <Teleport to="body">
    <div v-if="showDebug" id="vue-debug">
      <div class="handle" @click="toggleOpen">
        <div class="heading-wrapper">
        <span class="label"><strong>Vue</strong><span class="route-info" v-if="!isOpen">: {{ path }} [ {{routeName}} ]</span></span
        ><a @click="closeDebug">x</a>
        </div>
      </div>
      <div v-show="isOpen" class="main">
        <div>
          Current hash: {{ hash }}<br>
          Route name: {{ routeName }}
        </div>
        <hr />
        <div v-if="showComponents">
          <button @click="menu">Main Menu</button>
          <button @click="options">Options</button>
          <button @click="extra" v-if="EXTRA_ROUTE">⏩</button>
          <button @click="$simplemenu.value = !$simplemenu.value">{{ $simplemenu.value ? "✓" : "☐" }} SimpleMenu</button>
        </div>
        <div v-if="showComponents">
          <button @click="components">Components</button>
          <button @click="icons">Icons</button>
          <button @click="colours">Colours</button>
        </div>
        <select multiple @click="selectRoute">
          <option v-for="route in routes" :key="route">{{ route }}</option>
        </select>
      </div>
    </div>
  </Teleport>
</template>

<script setup>
import { useRoute } from "vue-router"
import { computed, ref } from "vue"
import router from "@/router"

const EXTRA_ROUTE = import.meta.env.VITE_MY_DEBUG_ROUTE

const routes = router
  .getRoutes()
  .map(r => r.name)
  .filter(n => n!=='routelist')
  .sort((a,b) => a.localeCompare(b))

const route = useRoute(),
  hash = ref(location.hash.split("#")[1]),
  path = computed(() => route.path),
  routeName = computed(() => route.name),
  showDebug = ref(window._VueDebugState),
  isOpen = ref(window._VueDebugOpen),
  showComponents = router.hasRoute("components")

const bngVue = window.bngVue || {}

bngVue.debug = (state = true) => (showDebug.value = window._VueDebugState = state)
bngVue.reset = () => bngVue.gotoGameState("menu.mainmenu")

function toggleOpen() {
  isOpen.value = window._VueDebugOpen = !isOpen.value
}

function selectRoute(e) {
  bngVue.gotoGameState(e.target.value)
}

function icons() {
  bngVue.gotoGameState("components/IconBrowser")
  toggleOpen()
}

function colours() {
  bngVue.gotoGameState("components/Colours")
  toggleOpen()
}

function extra() {
  bngVue.gotoGameState(EXTRA_ROUTE)
  toggleOpen()
}

function components() {
  bngVue.showComponents()
  toggleOpen()
}
function menu() {
  bngVue.reset()
  toggleOpen()
}

function options() {
  bngVue.gotoGameState("options")
}

// add component demo shortcut if we're in dev mode
if (process.env.NODE_ENV === "development") {
  bngVue.showComponents = () => {
    bngVue.gotoGameState("components")
  }
}

const closeDebug = e => {
  e.stopPropagation()
  bngVue.debug(false)
}

addEventListener("hashchange", e => {
  hash.value = e.newURL.split("#")[1]
})
</script>

<style lang="scss" scoped>
:root *:focus::before {
  content: none;
}

#vue-debug {
  z-index: var(--zorder_index_mdcontent) !important;
  position: absolute;
  background: #000c;
  color: white;
  right: 0;
  top: 42%;
  font-size: 10pt;
  // transform: translateY(2%);
  border-radius: var(--bng-corners-2);
  box-sizing: border-box;
  display: flex;
}

.main {
  padding: 1em 0.5em;
  box-sizing: border-box;
  background-color: #000d;
  overflow-x: auto;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: stretch;
  height: 20rem;
  > * {
    flex: 0 0 auto;
  }
  hr {
    width: 100%;
  }
  select {
    flex: 1 1 auto;
    margin-top: 1em;
  }
}

.handle {
  padding: 0.5rem 0.25rem;
  cursor: pointer;
  overflow: hidden;
  width: 1.5rem;
  box-sizing: border-box;
  height: 20rem;
  .heading-wrapper {
    width: 19rem;
    transform-origin: 0 0;
    transform: rotate(90deg) translateY(-100%);
    display: flex;
    .label {
      flex: 1 1 auto;
      white-space: nowrap;
      text-overflow: ellipsis;
      overflow: hidden;
    }
  }
}

.route-info {
  font-size:90%;
}
</style>
