<template>
  <div
    :class="{
      'mainmenu-container': true,
      'mainmenu-with-angular': withAngular,
      'mainmenu-fadein': firstTime && !withAngular,
    }"
    bng-ui-scope="mainmenuUI"
    v-bng-on-ui-nav:menu,back="handleBack"
  >
    <Slideshow
      v-if="bgRequired"
      class="background-image"
      ref="parentImageCarousel"
      :images="backgrounds.normal"
      transition
      :delay="10000"
    />
    <!-- this is to force the browser to show images right away by storing them in memory -->
    <template v-if="bgRequired">
      <div v-for="list in backgrounds" class="backgrounds-cache">
        <img v-for="src in list" :src="getAssetURL(src)" />
      </div>
    </template>
    <div class="main-view">
      <BngCard v-if="devEnv.env" class="dev-info">
        <BngCardHeading type="ribbon">Developer Release</BngCardHeading>
        <div class="dev-info-content">
          <BngIcon class="dev-info-icon" :type="icons.bug" bng-all-clicks-no-nav @click="doubleQuickLoadLevel()" />
          <div class="dev-info-text">
            <div>
              Graphics API: {{ devEnv.videoApi || "requesting..." }}
            </div>
            <div>
              UI Engine: {{ devEnv.UIEngine || "requesting..." }}
            </div>
          </div>
        </div>
      </BngCard>

      <div class="mainmenu-title">
        <Logo />
      </div>

      <!-- <ClassicView
        v-if="!viewName"
        :first-time="firstTime && !withAngular"
        :addons="addons"
        @change-view="changeView" /> -->

      <MainView
        v-if="!viewName"
        @change-view="changeView" />
      <OthersView
        v-else-if="viewName === 'others'"
        :addons="addons"
        @change-view="changeView" />
      <ExperienceView
        v-else-if="viewName === 'experience'"
        @change-view="changeView" />

      <div v-if="!viewName" class="bottom-buttons">
        <BngButton
          v-if="repoEnabled"
          class="btn-mods"
          :accent="ACCENTS.text"
          v-bng-blur="!bgRequired"
          v-bng-sound-class="'bng_click_hover_generic'"
          @click="navigate('menu.mods.repository')"
        >
          <BlurBackground v-if="bgRequired" />
          <div class="btn-content">
            <span class="label">{{ $tt("ui.mainmenu.repo") }}</span>
            <span class="small" v-if="modsTotal > 0">&nbsp;({{ modsActive }} / {{ modsTotal }})</span>
          </div>
        </BngButton>
        <BngButton
          v-else
          class="btn-mods"
          :class="{ 'mods-after-update': modsAfterUpdate }"
          :accent="ACCENTS.text"
          v-bng-blur="!bgRequired"
          v-bng-sound-class="'bng_click_hover_generic'"
          @click="navigate('menu.mods.local')"
        >
          <BlurBackground v-if="bgRequired" />
          <div class="btn-content">
            <span class="label">{{ $tt("ui.mainmenu.mods") }}</span>
            <span class="small" v-if="modsTotal > 0">&nbsp;({{ modsActive }} / {{ modsTotal }})</span>
          </div>
        </BngButton>
        <BngButton
          :accent="ACCENTS.text"
          v-bng-blur="!bgRequired"
          v-bng-sound-class="'bng_click_hover_generic'"
          @click="navigate('credits')"
        >
          <BlurBackground v-if="bgRequired" />
          <div class="btn-content">
            <span class="label">{{ $tt("ui.mainmenu.credits") }}</span>
          </div>
        </BngButton>
        <BngButton
          :accent="ACCENTS.text"
          v-bng-blur="!bgRequired"
          v-bng-sound-class="'bng_click_hover_generic'"
          @click="navigate('menu.options.display')"
        >
          <BlurBackground v-if="bgRequired" />
          <div class="btn-content">
            <span class="label">{{ $tt("ui.mainmenu.options") }}</span>
          </div>
        </BngButton>
        <BngButton
          v-if="devEnv.env"
          :accent="ACCENTS.text"
          :icon="icons.bug"
          v-bng-blur="!bgRequired"
          v-bng-sound-class="'bng_click_hover_generic'"
          @click="navigate('options')"
        >
          <BlurBackground v-if="bgRequired" />
          <div class="btn-content">
            <span class="label">{{ $tt("ui.mainmenu.options") }} WIP</span>
          </div>
        </BngButton>
        <BngButton v-if="!devEnv.simplemenu"
          class="btn-quit"
          :accent="ACCENTS.attention"
          :icon="icons.exit"
          v-bng-blur="!bgRequired"
          v-bng-sound-class="'bng_click_hover_generic'"
          @click="quitGame()"
        >
          <BlurBackground v-if="bgRequired" />
          <div class="btn-content">
            <span class="label">{{ $tt("ui.inputActions.general.quit.title") }}</span>
          </div>
        </BngButton>
      </div>

    </div>
  </div>
</template>

<script setup>
import { ref, reactive, computed, watch, onMounted, provide, nextTick } from "vue"
import { BngCard, BngCardHeading, BngButton, BngIcon, icons, ACCENTS } from "@/common/components/base"
import { vBngSoundClass, vBngOnUiNav, vBngBlur } from "@/common/directives"
import { useInfoBar } from "@/services/infoBar.js"
import { lua } from "@/bridge"
import { runRaw } from "@/bridge/libs/Lua.js"
import { useEvents } from "@/services/events"
import { $translate, SysInfo } from "@/services"
import { useSettingsAsync } from "@/services/settings"
import { useUINavScope } from "@/services/uiNav"
import { getAssetURL } from "@/utils"
import Slideshow from "../components/Slideshow.vue"
import BlurBackground from "../components/BlurBackground.vue"
import Logo from "../components/Logo.vue"
import ClassicView from "./ClassicView.vue"
import MainView from "./MainView.vue"
import OthersView from "./OthersView.vue"
import ExperienceView from "./ExperienceView.vue"

const events = useEvents()
const infoBar = useInfoBar()
useUINavScope("mainmenuUI")

const withAngular = computed(() => !SysInfo.mainMenuBackgroundRequired.value)
const firstTime = ref(SysInfo.mainMenuFirstTime.value)

/// backgrounds

const bgPathResolve = (product, name, blur = false) => `images/mainmenu/${product ? product + "/" : ""}${name}${blur ? "_blur" : ""}.jpg`
const _backgrounds = {
  unofficial: [bgPathResolve(null, "unofficial_version")],
  unofficial_blur: [bgPathResolve(null, "unofficial_version", true)],
  drive: Array.from({ length: 8 }, (_, i) => bgPathResolve("drive", i + 1)),
  drive_blur: Array.from({ length: 8 }, (_, i) => bgPathResolve("drive", i + 1, true)),
  tech: [bgPathResolve("tech", 1)],
  tech_blur: [bgPathResolve("tech", 1, true)],
}
const backgroundId = ref("drive")
const backgrounds = computed(() => ({
  normal: _backgrounds[backgroundId.value],
  blur: _backgrounds[backgroundId.value + "_blur"],
}))

const bgRequired = SysInfo.mainMenuBackgroundRequired

provide("backgroundsBlur", backgrounds.value.blur)
provide("backgroundRequired", bgRequired)

const parentImageCarousel = ref()
provide("mainCarousel", parentImageCarousel)

/// /backgrounds


/// dev thingy

const devEnv = reactive({
  env: window.beamng && !window.beamng.shipping,
  vue: process.env.NODE_ENV === "development",
  simplemenu: window.beamng && window.beamng.simplemenu,
  videoApi: null,
  UIEngine: null,
})

let dblClick = false
const doubleClick = callback => () => { // returns a function that will work on double-click only
  if (dblClick) {
    dblClick = false
    callback()
  } else {
    dblClick = true
    setTimeout(() => dblClick = false, 400)
  }
}

const quickLoadLevel = () => lua.core_levels.startLevel("/levels/smallgrid/main.level.json")
const doubleQuickLoadLevel = doubleClick(quickLoadLevel)

/// /dev thingy


/// addons

const addons = ref({})

const addButton = ({ translateid, icon, targetState, title, iconId, action }) => {
  let newButton
  if (translateid || icon || targetState) {
    // Angular style
    newButton = {
      title: $translate.instant(translateid),
      icon,
      action: targetState,
    }
  } else {
    // Vue style
    newButton = {
      title,
      iconId,
      action,
    }
  }
  addons.value[newButton.title] = newButton
}

/// /addons


const viewName = ref()
const changeView = name => viewName.value = name
watch(
  () => viewName.value,
  val => {
    !!val && infoBar.flashHints("back")
    parentImageCarousel.value && nextTick(parentImageCarousel.value.carousel.showNext)
  }
)

const navigate = (...state) => window.bngVue.gotoGameState(...state)

function quitGame() {
  lua.quit()
  runRaw("TorqueScript.eval('quit();')", false)
}

const handleBack = () => {
  if (viewName.value) {
    viewName.value = null
  } else {
    return true // let event bubble up and do a normal "back"
  }
}

// TODO: move to services; needs a unified service for messages
function displayToast(type, message) {
  const txt = $translate.instant(message)
  // const txt = $translate.instant("ui.hints.quickSteerResponse") // this is to test the bindings display
  // const html = $content.bbcode.parse(txt)
  const html = window.angularParseBBCode(txt) // use this to enable angular things
  window.globalAngularRootScope.$broadcast("toastrMsg", {
    type,
    msg: html,
    config: {
      positionClass: "toast-top-right",
      timeOut: 0,
      extendedTimeOut: 0,
      onTap() {
        window.bngVue.gotoGameState("menu.options.performance")
      }
    }
  })
}

async function checkHardware() {
  lua.checkFSErrors()
  const info = await lua.core_hardwareinfo.getInfo()
  if (info.globalState === "ok") return // all good
  for (var key in info) {
    if (!info[key].warnings || !Array.isArray(info[key].warnings)) continue
    for (const warning of info[key].warnings) {
      if (warning.ack) continue
      displayToast(
        info.globalState === "warn" ? "warning" : "error",
        "ui.performance.warnings." + warning.msg
      )
    }
  }
}

const repoEnabled = ref(false)
const modsAfterUpdate = ref(false)
const modsTotal = ref(0)
const modsActive = ref(0)

onMounted(async () => {
  function advertMainMenu() {
    events.emit("MainMenuButtons", addButton)
    window.globalAngularRootScope.$broadcast("MainMenuButtons", addButton)
  }
  advertMainMenu()
  events.on("BroadcastMainMenuButtons", advertMainMenu)
  // setTimeout(() => {
  //   beamng.sendEngineLua("sendUIModules()")
  // }, 3000)

  const isTech = await lua.extensions.tech_license.isValid()
  backgroundId.value = isTech ? "tech" : "drive"
  // FIXME: do we really need to check for this if we already confirmed the license?
  bngApi.engineLua("sailingTheHighSeas", ahoy => {
    backgroundId.value = ahoy ? "unofficial" : isTech ? "tech" : "drive"
  })

  if (devEnv.env) {
    devEnv.videoApi = await lua.Engine.Render.getAdapterType()
    devEnv.UIEngine = await lua.Engine.UI.getUIEngine()
  }

  if (SysInfo.mainMenuFirstTime.value) {
    checkHardware()
  }

  // TODO: check if it's already in infobar
  // fires OnlineRequestsState (always) and SteamInfo (optional) events
  // lua.core_online.requestState()

  const settings = await useSettingsAsync()
  modsAfterUpdate.value = settings.values.disableModsAfterUpdate
  repoEnabled.value = settings.values.onlineFeatures === "enable" && !settings.values.disableModsAfterUpdate

  events.on("ModManagerModsChanged", data => {
    const list = Object.values(data).filter(mod => mod.modname !== "translations")
    modsTotal.value = list.length
    modsActive.value = list.filter(mod => mod.active).length
  })
  // fires ModManagerModsChanged, ModManagerVehiclesChanged and onLevelsChanged events
  lua.core_modmanager.requestState()

  if (!isTech) {
    if (settings.values.onlineFeatures === "ask" || settings.values.telemetry === "ask") {
      window.bngVue.gotoGameState("menu.onlineFeatures")
    }
  }

  SysInfo.mainMenuFirstTime.value = false // to save the flag for later
})
</script>

<style lang="scss" scoped>
@use "@/styles/modules/mixins" as *;

$rem: calc-ui-rem();

.mainmenu-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  font-size: $rem;


  .background-image {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
  }
  &.mainmenu-with-angular { // note: we're *assuming* that we're visually wrapped with angular
    margin-top: 2.5em;
  }
}

.mainmenu-fadein .main-view {
  animation: fadein 1.5s;
  @keyframes fadein {
    0%, 50% { opacity: 0; }
    100% { opacity: 1; }
  }
}

.backgrounds-cache {
  // this must not be display:none; in order to work
  position: absolute;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  opacity: 0;
  overflow: hidden;
}

.mainmenu-title {
  margin-bottom: 3em !important;
}

.main-view {
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: absolute;
  width: 100%;
  height: calc(100% - 3em);
}

.bottom-items {
  display: flex;
  flex-direction: row;
  justify-content: center;
  pointer-events: all;
}

.mods-top {
  position: absolute;
  top: 1em;
  left: 1em;
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  gap: 1em;
  pointer-events: all;
}

.dev-info {
  position: absolute;
  top: 1em;
  left: 1em;
  min-width: 20em;
  color: white;
  pointer-events: all;
  .dev-info-icon {
    font-size: 3em;
  }
  .dev-info-content {
    display: flex;
    align-items: center;
    padding: 5px 10px 10px 10px;
    font-weight: bold;
    font-size: 20px;
    font-family: Roboto;
    border-radius: var(--bng-corners-1);
  }
  .dev-info-text {
    padding-left: 0.5em;
    > * {
      display: block;
      margin-bottom: 0.5em;
    }
  }
}

.bottom-buttons {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(calc-ui-rem(12), 1fr));
  padding: 0 $rem;
  width: calc-ui-rem(64);
  align-self: center;
  > * {
    min-height: 2.5em;
    font-size: 1.2em;
    pointer-events: all;
  }
  .btn-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
  }
  .btn-mods {
    // background-color: rgba(var(--bng-orange-750-rgb), 0.6) !important;
    .label {
      line-height: 1.2;
    }
    .small {
      font-size: calc-ui-rem(0.8);
      line-height: 1.2;
    }
    &.mods-after-update {
      position: relative;
      :deep(.background) {
        font-size: $rem;
        $color: var(--bng-add-red-600-rgb);
        box-shadow: inset 0 0 0 calc-ui-rem(0.125) rgba($color, 1);
        background-image:
          linear-gradient(-45deg, rgba($color, 0) calc(50% - 0.124em), rgba($color, 1) calc(50% - 0.125em), rgba($color, 1) calc(50% + 0.125em), rgba($color, 0) calc(50% + 0.126em)),
          linear-gradient(90deg, rgba(0, 0, 0, 0.80) 0%, rgba(0, 0, 0, 0.50) 30%, rgba(0, 0, 0, 0.00) 50%, rgba(0, 0, 0, 0.50) 70%, rgba(0, 0, 0, 0.80) 100%),
          repeating-linear-gradient(-45deg, rgba($color, 0), rgba($color, 0) 0.424em, rgba($color, 0.8) 0.425em, rgba($color, 0.8) 0.55em);
      }
      .label, .small {
        opacity: 1;
      }
    }
  }
  .btn-quit {
    :deep(.background) {
      opacity: 0.6;
    }
    &:hover {
      :deep(.background) {
        opacity: 1;
      }
    }
  }
}

</style>
