<!-- bngBinding - visually display an action binding -->
<template>
  <span v-if="display && ( viewerObj || showUnassigned )" :ui-event="uiEvent" class="binding-wrap">
    <!-- control uses a generic representation -->
    <kbd :class="{ light: !dark, dark }" v-if="viewerObj && (!viewerObj.special || viewerObj.ownLabel)">
      <span>
        <BngIcon
          class="bng-binding-icon"
          :type="icons[viewerObj.icon]"
          :color="dark ? 'rgb(250, 250, 250)' : '#000'"
        />
        <span class="bng-binding-label">{{ viewerObj.ownLabel || viewerObj.control }}</span>
      </span>
    </kbd>
    <!-- control uses a dedicated icon -->
    <BngIcon
      v-if="viewerObj && viewerObj.special"
      class="bng-binding-icon"
      :type="icons[viewerObj.ownIcon]"
      :color="dark ? '#000' : 'rgb(250, 250, 250)'"
    />
    <!-- control is not assigned, fallback to empty display -->
    <BngIcon
      v-if="!viewerObj && showUnassigned"
      class="bng-binding-icon n-a"
      :type="icons.NA"
      :color="dark ? '#000' : 'rgb(250, 250, 250)'"
    />
    <!-- <kbd :class="{ light: !dark, dark: dark }" v-if="!viewerObj && showUnassigned">
      <span<span class="n-a">{{ unassignedText }}</span></span>
    </kbd> -->
  </span>
</template>

<script setup>
import { computed, watch, onMounted, onUnmounted, inject } from "vue"
import { BngIcon, icons } from "@/common/components/base"
import useControls from "@/services/controls"
import { useUINavTracker } from "@/services/uiNavTracker"
import { uniqueId } from "@/services/uniqueId"

const Controls = useControls()
const $simplemenu = inject("$simplemenu")

const props = defineProps({
  action: String,
  showUnassigned: Boolean,
  device: String,
  deviceKey: String,
  dark: Boolean,
  deviceMask: [String, Function],
  controller: Boolean, // use this instead of deviceMask to check for any controller
  uiEvent: String,
  trackIgnore: Boolean,
  unassignedText: {
    default: "[N/A]",
    type: String,
  },
  viewerObj: Object,
})

const viewerObj = computed(() => props.viewerObj || Controls.makeViewerObj(props))
const isController = Controls.isGamepadAvailable(true) // or isKnownGamepadAvailable

const display = computed(() => {
  if (viewerObj.value) {
    if (props.deviceMask) {
      const dev = viewerObj.value.devName
      if (typeof props.deviceMask === "function") return props.deviceMask(dev)
      return dev.startsWith(props.deviceMask)
    }
    if (props.controller || $simplemenu.value) {
      return isController.value
    }
  }
  return true
})

defineExpose({
  displayed: display,
})

const eventName = computed(() => {
  if (props.action) return props.action
  if (props.uiEvent) return props.uiEvent
  return null
})

const uiNavTracker = useUINavTracker()
const ownerId = uniqueId("bngBinding")
let trackedEvent = ""

const track = (eventName = null) => {
  if (trackedEvent) {
    uiNavTracker.removeIgnore(trackedEvent, ownerId)
    trackedEvent = ""
  }
  if (props.trackIgnore || !display.value) return
  if (eventName) {
    if (trackedEvent === eventName) return
    trackedEvent = eventName
    uiNavTracker.addIgnore(trackedEvent, ownerId)
  }
}

watch(
  () => props.trackIgnore,
  val => track(val ? null : eventName.value)
)
watch(
  display,
  () => track(eventName.value)
)
watch(
  eventName,
  (val, prev) => {
    prev && track()
    val && track(val)
  }
)

onMounted(() => track(eventName.value))
onUnmounted(() => track())
</script>

<style lang="scss" scoped>
.binding-wrap {
  font-style: normal;
  text-decoration: none;
}

kbd {
  vertical-align: middle;
  display: inline-block;
  margin-right: 0.125em;
  margin-left: 0.125em;
  min-width: 1em;
  padding: 0 0.25em;
  font-family: var(--fnt-mono);
  font-weight: 600;
  text-align: center;
  text-decoration: none;
  border-radius: var(--bng-corners-1);
  border: none;
  user-select: none;
  --bng-icon-size: 1.25em;
  line-height: 1em;
  & > span {
    text-transform: uppercase;
    display: inline-flex;
    align-items: center;
    & > span {
      font-size: 0.75em;
      line-height: 1em;
      padding-bottom: 0;
      position: relative;
      padding-right: 0.125em;
    }
  }
  .bng-binding-icon {
    font-size: 1.25em;
    line-height: 1.25em;
  }
}

kbd,
kbd.dark,
.dark-keys kbd,
.key,
.key.dark,
.dark-keys .key {
  background: rgb(80, 80, 80);
  background: -moz-linear-gradient(top, rgb(60, 60, 60), rgb(80, 80, 80));
  background: -webkit-gradient(linear, left top, left bottom, from(rgb(60, 60, 60)), to(rgb(80, 80, 80)));
  color: rgb(250, 250, 250);
}

kbd.light,
.light-keys kbd,
.key.light,
.light-keys .key {
  background: rgb(250, 250, 250);
  background: -moz-linear-gradient(top, rgb(210, 210, 210), rgb(255, 255, 255));
  background: -webkit-gradient(linear, left top, left bottom, from(rgb(220, 220, 220)), to(rgb(240, 240, 240)));
  color: rgb(0, 0, 0);
  border: solid;
  border-width: 1px;
  border-color: rgba(0, 0, 0, 0.2);
}

.bng-binding-icon {
  font-size: 2em;
  line-height: 1em;
  display: inline-block;
  vertical-align: baseline;
  transform: none;
  &.n-a {
    --bng-icon-size: 1.75em;
  }
  font-weight: 400 !important;
}

.bng-binding-label {
  white-space: nowrap;
}
</style>
