<template>
  <div class="bng-stars">
    <div v-if="individualStars && individualStars.length" class="individual-stars">
      <div v-for="(isFilled, index) in individualStars"
           :key="index"
           class="star"
           :class="{ 'filled': isFilled }"> </div>
    </div>
    <div v-else-if="numerical" class="individual-stars">
      <div class="text">
        {{unlockedStars}} / {{totalStars}}
      </div>
      <div class="star filled"> </div>
    </div>
    <div v-else class="stars-bar"></div>
  </div>
</template>

<script>
const STAR_WIDTH = 1.5
const STAR_WIDTH_UNIT = "rem"
</script>

<script setup>
import { getAssetURL } from "@/utils"
import { computed } from "vue"
const iconImageURL = getAssetURL("icons/general/star.svg") // TODO - fix hardcoded icon path - use from list

const props = defineProps({
  unlockedStars: {
    type: Number,
    default: 0,
    validator(value) {
      return value >= 0
    },
  },
  totalStars: {
    type: Number,
    default: 1,
  },
  scale: {
    type: Number,
    default: 1,
  },
  individualStars: {
    type: Object,
    default: null
  },
  numerical : {
    type: Boolean,
    default: false
  },
})

const starBarsWidth = computed(() => `${props.totalStars * STAR_WIDTH * props.scale + 0.05}${STAR_WIDTH_UNIT}`)
const starBarsHeight = computed(() => `${1.5 * props.scale}${STAR_WIDTH_UNIT}`)
const fontSize = computed(() => `${1.25 * props.scale}${STAR_WIDTH_UNIT}`)
const backgroundPosition = computed(() => `${100 - Math.floor((props.unlockedStars / props.totalStars) * 100)}%`)
const starIconUrlStyle = computed(() => `url(${iconImageURL})`)
</script>

<style scoped lang="scss">
@import "@/styles/modules/density";

$defaultStarColor: #ffff;
$starColor: var(--star-color, $defaultStarColor);

.bng-stars {
  border-radius: $border-rad-1;
  background: rgba(black, 0.6);
  padding: 0.5rem;

  .individual-stars {
    display: flex;
    align-items:center;
    .text {
      font-size: v-bind(fontSize);
      font-weight: 400;
      padding-right: 0.25rem;
    }

    .star {
      width: v-bind(starBarsHeight);
      height: v-bind(starBarsHeight);
      background: no-repeat center/contain v-bind(starIconUrlStyle);
      background: rgba(255, 255, 255, 0.2);
      -webkit-mask-image: v-bind(starIconUrlStyle);
      -webkit-mask-repeat: space;
      -webkit-mask-size: contain;
      -webkit-mask-position: 50% 50%;
      &.filled {
        background: $starColor;
      }
    }
  }

  > .stars-bar {
    background: no-repeat linear-gradient(90deg, $starColor 50%, rgba(255, 255, 255, 0.2) 50%) 0 0 / 200% 200%;
    -webkit-mask-image: v-bind(starIconUrlStyle);
    -webkit-mask-repeat: space;
    -webkit-mask-size: contain;
    -webkit-mask-position: 50% 50%;
    width: v-bind(starBarsWidth);
    height: v-bind(starBarsHeight);
    flex: 0 0 auto;
    transition: background-position 0.2s ease;
    background-position: v-bind(backgroundPosition);
    content: "";
  }

}
</style>
