<script setup>
import {ref, onMounted, computed} from 'vue'

const width  = 660
const height = 660
const initialized = ref(false)
const pressure_redline_len = 0
const dashSize = 5

// pressure
const pressureTextRef = ref(null)

// pressureCurve
const pressureCurveRef = ref(null)
const pressureCurveLen = computed(() => pressureCurveRef.value.getTotalLength())

// pressureCurve dashes
const pressureCurveDashesRef = ref(null)
const pressureCurveDashesLen = computed(() => pressureCurveDashesRef.value.getTotalLength())

// redline
const redLineRef = ref(null)
const redLineLen = computed(() => redLineRef.value.getTotalLength())

// pressureTextGuideLine -- a helping line to position the text
const pressureTextGuideLineRef = ref(null)
const pressureTextGuideLineLen = computed(() => pressureTextGuideLineRef.value.getTotalLength())

// the pressure text
const pressureTextSize = 50 // in px
const dashCount = 5
const pressureTextRefs = ref([])
const pressureTextAttrs = ref([
    {
        id: 'pressuretext1',
        x: 197.49423,
        y: 531.5639,
        text: 1
    },
    {
        id: 'pressuretext2',
        x: 124.71793,
        y: 434.92328,
        text: 2
    },
    {
        id: 'pressuretext3',
        x: 110.04411,
        y: 303.35791,
        text: 3
    },
    {
        id: 'pressuretext4',
        x: 165.89227,
        y: 187.39682,
        text: 4
    },
    {
        id: 'pressuretext5',
        x: 284.48657,
        y: 123.71478,
        text: 5
    },
    {
        id: 'pressuretext6',
        x: 419.43579,
        y: 137.55835,
        text: 6
    },
    {
        id: 'pressuretext7',
        x: 520.0791,
        y: 228.94992,
        text: 7,
    },
    {
        id: 'pressuretext8',
        x: 520.0791,
        y: 228.94992,
        text: 8,
    },
    {
        id: 'pressuretext9',
        x: 520.0791,
        y: 228.94992,
        text: 9,
    },
    {
        id: 'pressuretext10',
        x: 520.0791,
        y: 228.94992,
        text: 10,
    }
])
const pressureTSpanRefs = ref([])

const PRESURE_MAX_CONST = 150
const PRESURE_MIN_CONST = -100
const pressureMax = ref(null)
const pressureMin = ref(null)
//dashCount = 3; // this can artifically limit the number of rpm splits

// pressure_needle
const pressureNeedleRef = ref(null)
const pressureUnitRef = ref(null)

var displayMode = ref(2)

const UiUnitscallback = ref(() => null)
const roundDecCallback = ref(() => 0)

onMounted(() => {
    pressureTextRef.value.textContent = ''
    pressureCurveRef.value.style.strokeDasharray = pressureCurveLen.value + ' ' + pressureCurveLen.value
    pressureTextGuideLineRef.value.style.display = 'none'

    // setup + hide all
    // for(var k=1; k < dashCount + 3; k++) {
    //     document.getElementById('pressuretext' + k).style['visibility'] = 'hidden';
    //     document.getElementById('pressuretext' + k).style['font-size'] = pressureTextSize + 'px';
    // }

    for(var k=0; k < dashCount + 2; k++) {
        pressureTextRefs.value[k].style.visibility = 'hidden';
        pressureTextRefs.value[k].style.fontSize = pressureTextSize + 'px';
    }
})

function update(streams) {
  const streamData = streams.forcedInductionInfo
  // real data mode, no animation

  pressureMax.value = Math.ceil(UnitPressure(Math.max(PRESURE_MAX_CONST, streamData.maxBoost)))
  pressureMin.value = Math.floor(UnitPressure(PRESURE_MIN_CONST))

  if(!initialized.value) {

    reset()

    var redline_perc = 0.8 //TODO: should make this calculated with engine damage that can make the turbo

    redLineRef.value.style.strokeDasharray = redLineLen.value + ' ' + redLineLen.value
    redLineRef.value.style.strokeDashoffset = -redline_perc * redLineLen.value


    var dashes = (pressureCurveDashesLen.value - dashSize * dashCount) / (dashCount + 1)
    pressureCurveDashesRef.value.style.strokeDasharray = dashSize + ' ' + dashes
    pressureCurveDashesRef.value.style.strokeDashoffset = dashSize

    // setup and move the pressure gauge text

    var lastT = 0;
    for(var k = 0 ; k < dashCount + 2; k++) {
      var pos = pressureTextGuideLineRef.value.getPointAtLength(pressureTextGuideLineLen.value * (k / (dashCount + 1)))

    //   var rp = document.getElementById('pressuretext' + (k + 1) + 'p')
    //   var cx = rp.getAttribute('x')
    //   var cy = rp.getAttribute('y')
    //   rp.setAttribute('transform','translate(' + (pos.x - cx) + ',' + (pos.y - cy ) + ')')
    //   document.getElementById('pressuretext' + (k + 1)).textContent = roundDecCallback.value(
    //     k * ((pressureMax.value - pressureMin.value) / (dashCount + 1)) + pressureMin.value, 
    //     (pressureMax.value > 10 ? 0 : 1))
    //   document.getElementById('pressuretext' + (k + 1)).style['visibility'] = 'visible'

      const rp = pressureTextRefs.value[k]
      const cx = rp.getAttribute('x')
      const cy = rp.getAttribute('y')
      const rpSpan = pressureTSpanRefs.value[k]
      rp.setAttribute('transform','translate(' + (pos.x - cx) + ',' + (pos.y - cy ) + ')')
      rpSpan.textContent = roundDecCallback.value(
        k * ((pressureMax.value - pressureMin.value) / (dashCount + 1)) + pressureMin.value, 
        (pressureMax.value > 10 ? 0 : 1))
      rpSpan.style.visibility = 'visible'
    }
    initialized.value = true
  }

  // if(streams.forcedInductionInfo.boost &lt; 0 &amp;&amp; unitSystem != "metric")
  // {
  //   //psi to in.HG when pressure is vaccum
  //   data.psi = (streams.forcedInductionInfo.boost * 2.03) / (30 * 2);
  //   data.pressureText = streams.forcedInductionInfo.boost * 2.03;
  // }
  // else
  // {
  //   data.pressureText = streams.forcedInductionInfo.boost * pressureunitMultiplier;
  //   data.psi = streams.forcedInductionInfo.boost / pressure_max;
  // }

  applyData(streamData)
}

function reset() {
  initialized.value = false;
//   for(var k=1; k < dashCount + 3; k++) {
//     document.getElementById('pressuretext' + k).style['visibility'] = 'hidden';
//   }

    for(var k=0; k < dashCount + 2; k++) {
        pressureTSpanRefs.value[k].style.visibility = 'hidden';
    }
}

function isStreamValid(streams) {
    return !!streams.forcedInductionInfo
}

function wireThroughUnitSystem(callback) {
  UiUnitscallback.value = callback;
}

function wireThroughRoundDec(callback) {
    roundDecCallback.value = callback
}

defineExpose({
    reset,
    isStreamValid,
    update,
    wireThroughUnitSystem,
    wireThroughRoundDec
})

function applyData(data) {
  var boost = UnitPressure(data.boost)

  pressureTextRef.value.textContent = roundDecCallback.value(boost, 1)

  // (boost % of scala) / (displayed range)
  var percPos = (boost - pressureMin.value) / (pressureMax.value - pressureMin.value)

  // just in case the boost has inconsistent data
  if (percPos < 0) {
    percPos = 0
  }
  if (percPos > 1) {
    percPos = 1
  }

  // % of scala * scala deg
  // orig transform is vertical so -135 to "move" 0 to start of curve
  pressureNeedleRef.value.setAttribute('transform','rotate(' + (percPos * 270 - 135) + ',' + (width / 2) + ',' + (height / 2) + ')')

  // 0 offset means the whole thing is filled white. pressureCurveLen it's not filled at all
  pressureCurveRef.value.style.strokeDashoffset = pressureCurveLen.value - (pressureCurveLen.value * percPos)
}

function UnitPressure (val) {
  var convertedVal = UiUnitscallback.value(val, 'pressure');

  if (pressureNeedleRef.value.textContent !== convertedVal.unit) {
    pressureUnitRef.value.textContent = convertedVal.unit;
    // the scala needs to be changed
    initialized.value = false;
  }

  return convertedVal.val;
}
</script>

