<template>
  <BngSelect
    v-if="type === 'select'"
    class="bng-smart-select"
    v-model="value"
    :options="items"
    :config="selConfig"
    :disabled="disabled"
    @change="emit('change', $event)"
  />
  <BngDropdown
    v-else
    class="bng-smart-dropdown"
    v-model="value"
    :items="items"
    :highlight="highlight"
    :disabled="disabled"
    @valueChanged="emit('change', $event)"
    show-search
  />
</template>

<script setup>
import { computed, defineModel } from "vue"
import { BngSelect, BngDropdown } from "@/common/components/base"

const props = defineProps({
  items: {
    type: Array,
    required: true,
  },
  threshold: {
    type: Number,
    default: 5,
  },
  type: {
    type: String,
    default: "",
    validator(val) {
      return ["", "select", "dropdown"].includes(val)
    },
  },
  highlight: [String, Array, RegExp],
  disabled: Boolean,
})

const value = defineModel()

const emit = defineEmits(["change"])

const selConfig = {
  label: x => x.label,
  value: x => x.value,
}

const items = computed(() => {
  if (!props.items || !Array.isArray(props.items)) return []
  // filter items that aren't supported by BngSelect
  const selItems = props.items.filter(itm => !itm.disabled && !itm.group)
  // select
  if (selItems.length <= props.threshold) {
    return selItems
  }
  // dropdown
  return props.items
})

const type = computed(() => items.value.length <= props.threshold ? "select" : "dropdown")
</script>

<style lang="scss">
.bng-smart-select {
  --indicator-size: 2px;
  --indicator-padding: 2.25em;
  padding: 0 !important;
  > button {
    margin: 0 !important;
  }
}
</style>
