<template>
  <div class="overflow-container-demo-page">
    <div>
      <label>Basic Overflow Container with Buttons</label>
      <BngOverflowContainer
        ref="elCont"
        :scroll-speed="scrollSpeed"
        @scroll="onScroll"
      >
        <BngButton v-for="(button, idx) in buttons" :key="idx" class="demo-button" :accent="ACCENTS[button.accent]">
          {{ button.label }}
        </BngButton>
      </BngOverflowContainer>
    </div>

    <div>
      <label>Mixed Content</label>
      <BngOverflowContainer :scroll-speed="scrollSpeed">
        <BngButton class="demo-button" :accent="ACCENTS.outlined">Action 1</BngButton>
        <BngButton class="demo-button" :accent="ACCENTS.outlined">Action 2</BngButton>
        <BngButton class="demo-button" :accent="ACCENTS.outlined">Action 3</BngButton>
        <BngButton class="demo-button" :accent="ACCENTS.outlined">Action 4</BngButton>
        <div class="demo-content">Custom Content</div>
        <BngButton class="demo-button" :accent="ACCENTS.outlined">Another Button</BngButton>
        <div class="demo-badge">Badge</div>
        <BngButton class="demo-button" :accent="ACCENTS.outlined">Final Button</BngButton>
      </BngOverflowContainer>
    </div>

    <div class="actions">
      <BngButton class="btn" @click="scrollToLeft">Scroll to Left</BngButton>
      <BngButton class="btn" @click="scrollToRight">Scroll to Right</BngButton>
      <BngButton class="btn" @click="scrollBy(-100)">Scroll Left 100px</BngButton>
      <BngButton class="btn" @click="scrollBy(100)">Scroll Right 100px</BngButton>
      <BngInput v-model="scrollSpeed" type="number" floating-label="Scroll speed" />
    </div>

    <div class="scroll-info" v-if="nfo">
      <p>Scroll Position: {{ nfo.scrollLeft }}px</p>
      <p>Total Width: {{ nfo.scrollWidth }}px</p>
      <p>Visible Width: {{ nfo.clientWidth }}px</p>
    </div>
  </div>
</template>

<script setup>
import { ref } from "vue"
import { BngButton, ACCENTS, BngInput } from "@/common/components/base"
import { BngOverflowContainer } from "@/common/components/base"

const elCont = ref(null)
const nfo = ref(null)

const scrollSpeed = ref(5)

const buttons = [
  { label: "Home", accent: "primary" },
  { label: "Garage", accent: "secondary" },
  { label: "Career", accent: "outlined" },
  { label: "Options", accent: "text" },
  { label: "Quit", accent: "attention" },
  { label: "Mods", accent: "secondary" },
  { label: "Replay", accent: "primary" },
  { label: "Photo Mode", accent: "secondary" },
  { label: "Freeroam", accent: "outlined" },
  { label: "Scenarios", accent: "text" },
]

const scrollToLeft = () => elCont.value.scrollToLeft()
const scrollToRight = () => elCont.value.scrollToRight()
const scrollBy = amount => elCont.value.scrollBy(amount)
const onScroll = info => nfo.value = info
</script>

<style scoped lang="scss">
.overflow-container-demo-page {
  display: flex;
  flex-direction: column;
  gap: 2em;
  padding: 1em;

  > div {
    display: flex;
    flex-direction: column;
    gap: 0.5em;

    label {
      font-weight: bold;
      color: var(--bng-cool-gray-200);
    }
  }
}

.actions {
  flex-direction: row !important;
  flex-wrap: wrap;

  .btn {
    margin: 4px;
  }
}

.demo-button {
  flex-shrink: 0;
  min-width: max-content;
}

.demo-content {
  background: var(--bng-cool-gray-700);
  padding: 0.5em 1em;
  border-radius: 0.5em;
  color: var(--bng-cool-gray-200);
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.demo-badge {
  background: var(--bng-orange-b400);
  color: white;
  padding: 0.25em 0.75em;
  border-radius: 1em;
  font-size: 0.8em;
  font-weight: bold;
  flex-shrink: 0;
  display: flex;
  align-items: center;
}

.scroll-info {
  background: var(--bng-cool-gray-800);
  padding: 1em;
  border-radius: 0.5em;
  font-family: monospace;
  font-size: 0.9em;

  p {
    margin: 0.25em 0;
    color: var(--bng-cool-gray-300);
  }
}
</style>

<script>

// Demo Metadata
// -------------------------------------------------------
import source from "./bngOverflowContainer_demo.vue?raw"
export default {
  source,
  title: "Overflow Container",
  description: `A generic container with horizontal scrolling and fade effects that can contain any content`,
  propInfo: [
    {
      name: "scrollSpeed",
      type: "Number",
      desc: "Controls the speed of automatic scrolling when hovering over fade areas. Default is 5.",
    },
  ],
  attrInfo: [
    {
      name: "@scroll",
      type: "Event",
      desc: "Emitted when the container scrolls, provides scroll information object with scrollLeft, scrollWidth, and clientWidth properties",
    },
  ],
}

</script> 