<template>
  <div class="center-wrap">
    <BngScreenHeading class="exp-header" divider type="line">
      {{ $tt("ui.experiences.general.quickStart") }}
    </BngScreenHeading>
    <div class="exp-wrapper">

      <div class="exp-container">
        <BackAside @click="emit('changeView', null)" />

        <BngCard class="exp-content" v-bng-blur="!bgRequired">
          <BlurBackground v-if="bgRequired" class="corners-big" />
          <template v-for="(section, index) in sections" :key="section.key">
            <div v-if="index > 0" :class="{ 'exp-separator': true, 'exp-desc-active': descShow }">
              <Transition name="desc-appear">
                <div v-if="descShow" class="exp-card-desc">
                  {{ $tt(descText) }}
                </div>
              </Transition>
            </div>
            <div class="exp-buttons">
              <template v-if="section.cards.length === 0">
                <MenuButton
                  v-for="i in section.placeholders" :key="i"
                  disabled
                  :size="section.size" no-blur
                  :bg-img="section.size === 'big' ? '/images/mainmenu/freeroam.jpg' : null"
                  :style="section.style"
                >{{ i === 1 ? $tt("ui.repository.loading") : "" }}</MenuButton>
              </template>
              <template v-else>
                <MenuButton
                  v-for="card in section.cards" :key="card.discoverId"
                  v-bng-ui-nav-focus="firstCardId && firstCardId === card.discoverId ? 0 : undefined"
                  :size="section.size" no-blur
                  :bg-img-abs="card.image"
                  @click="startDiscover(card.discoverId)"
                  @mouseenter="setDescription('hover', card)"
                  @mouseleave="setDescription('hover')"
                  @focus="setDescription('focus', card)"
                  @blur="setDescription('focus')"
                  :enlarge-on-hover="true"
                  :darkened-image="section.size === 'medium'"
                  :text-icon-prefix="section.size == 'medium' && card.icon"
                  :style="section.style"
                  :tag="$ctx_t(card.tag)"
                >{{ $tt(card.name) }}</MenuButton>
              </template>
            </div>
          </template>
        </BngCard>

      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, inject } from "vue"
import { BngCard, BngScreenHeading } from "@/common/components/base"
import { vBngUiNavFocus, vBngBlur } from "@/common/directives"
import { useBridge } from "@/bridge"
import MenuButton from "../components/MenuButton.vue"
import BlurBackground from "../components/BlurBackground.vue"
import BackAside from "../components/BackAside.vue"
const { lua } = useBridge()

const emit = defineEmits(["changeView"])

const bgRequired = inject("backgroundRequired")

const discoverCards = ref([])

const descShow = ref(false)
const descText = ref(null)
const descriptions = {
  hover: null,
  focus: null,
}
let descTimer

function setDescription(type, card = undefined) {
  if (descTimer) clearTimeout(descTimer)
  descriptions[type] = card?.description
  if (card) {
    descShow.value = true
    descText.value = card.description
  } else if (type === "hover" && descriptions.focus) {
    descText.value = descriptions.focus
  } else {
    descTimer = setTimeout(() => {
      descShow.value = false
      descTimer = setTimeout(() => {
        descText.value = null
        descTimer = null
      }, 200) // transition time
    }, 100) // cooldown
  }
}

const sections = computed(() => {
  const res = [
    { title: "Freeroam Experiences", cards: [], placeholders: 5, size: "big" },
    { title: "Showcase Challenges", cards: [], placeholders: 10, size: "medium", style: { "--button-height": "4.5em" } },
  ]
  let stamp = Date.now()
  if (discoverCards.value?.freeroam) {
    for (const card of discoverCards.value.freeroam) {
      const section = res[card.missionId ? 1 : 0]
      section.cards.push(card)
      section.key = stamp++ // for reactivity
    }
  }
  return res
})

const firstCardId = computed(() => sections.value.find(s => s.cards[0])?.cards[0]?.discoverId)

const starting = ref(false)

function startDiscover(discoverId) {
  starting.value = true
  lua.gameplay_discover.startDiscover(discoverId)
}

async function loadDiscoverCards() {
  await lua.extensions.load("gameplay_discover")
  discoverCards.value = await lua.gameplay_discover.getDiscoverCards()
  console.log("discoverCards", discoverCards.value, "firstCardId", firstCardId.value)
}

onMounted(() => {
  loadDiscoverCards()
  //setTimeout(loadDiscoverCards, 1)
})
</script>

<style lang="scss" scoped>
@use "@/styles/modules/mixins" as *;

$button-width: 16em;
$buttons-per-row: 5;
$rem: calc-ui-rem();

.center-wrap {
  align-self: center;

  display: flex;
  flex-flow: column nowrap;
  align-items: stretch;
  margin: 0 calc-ui-rem(15);
}

.exp-wrapper {
  width: calc($button-width * $buttons-per-row + 0.7em * $buttons-per-row);
  margin-bottom: 3.5em;
  margin-left: auto;
  margin-right: auto;
  width: 100%;
}

.exp-header {
  margin-left: calc-ui-rem(-4.25);
}

.exp-container {
  position: relative;
  padding: 0.25em;

  .exp-heading {
    flex: 0 0 100%;
    color: #fff;
  }

  .exp-content {
    --bg-opacity: 0.4;
    display: flex;
    flex-direction: column;
    justify-content: start;
    align-items: stretch;
    font-size: $rem;
  }
  :deep(.card-cnt) {
    padding: 0.5em;
    gap:1em;
  }
}

.exp-buttons {
  pointer-events: all;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  align-items: stretch;
  gap: 0.25em;
}

.exp-separator {
  position: relative;
  display: block;
  height: 3em;
  margin: -0.5em 0.25em;
  &::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: linear-gradient(90deg,
      rgba(var(--bng-orange-400-rgb), 0) 0%,
      var(--bng-orange-400) 15%,
      var(--bng-orange-400) 85%,
      rgba(var(--bng-orange-400-rgb), 0) 100%
    );
    background-size: 95% 3px;
    background-position: 50% 50%;
    background-repeat: no-repeat;
    transition:
      background-size 200ms ease-in-out,
      opacity 200ms ease-in-out;
  }
}
.exp-desc-active::before {
  background-size: 95% 0px;
  opacity: 0;
}

.exp-card-desc {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: block;
  max-height: 100%;
  width: 80%;
  $rem2: calc-ui-rem(2);
  padding: 0.35em $rem2 0.1em 2em;
  font-size: $rem;
  border-radius: 0.5em;
  color: white;
  background-image: linear-gradient(
    90deg,
    #0000 0%,
    #0008 $rem2 calc(100% - $rem2),
    #0000 100%
  );
  background-size: 100% 100%;
  opacity: 1;
  overflow: hidden;
  pointer-events: none;
  text-align: center;
}

.desc-appear-enter-active,
.desc-appear-leave-active {
  transition:
    opacity 200ms ease-in-out,
    max-height 200ms ease-in-out;
}
.desc-appear-enter-from,
.desc-appear-leave-to {
  opacity: 0.5;
  max-height: 0%;
}
</style>
