<template>
  <div class="main-container">
    <div class="cached-score-wrapper">
      <div class="fail-overlay" :class="{ active: isFailActive }"></div>
      <div class="performance-background" :style="{
        transform: `scaleY(${Math.min(steppedPerformanceFactor / 3, 1)}) scaleX(${Math.min(steppedPerformanceFactor / 3, 1)})`,
        transformOrigin: 'center bottom',
        background: steppedPerformanceFactor >= 4
          ? 'radial-gradient(ellipse at center bottom, rgba(30, 200, 30, 1), rgba(30, 200, 30, 0.8) 20%, rgba(30, 200, 30, 0.4) 50%, transparent 70%)'
          : 'radial-gradient(ellipse at center bottom, rgba(255, 102, 0, 1), rgba(255, 102, 0, 0.8) 20%, rgba(255, 102, 0, 0.4) 50%, transparent 70%)'
      }"></div>
      <template v-if="centerFailMessage">
        <div class="center" :class="{ 'fade-out': isCenterMessageFading }">
          {{centerFailMessage}}
        </div>
      </template>
      <template v-else-if="centerMessage">
        <div class="center" :class="{ 'fade-out': isCenterMessageFading }">
          {{centerMessage}}
          <template v-if="centerMessage && scoreToAdd >= 0">{{scoreToAdd}}</template>
        </div>
      </template>
      <template v-else>
        <div class="added-score">
          <div v-for="(item, index) in bonusDisplay" :key="index" class="score-item">
            +{{ ~~item.score }}
          </div>
        </div>
        <div class="cached-score">
          <div class="score-container">
            <div class="score-modifier"
                 :key="currentModifier"
                 :class="{ 'fade-out': isModifierFading }">
              {{ currentModifier }}
            </div>
            <div class="score">{{ realtimeScorePoints }}</div>
          </div>
          <div class="combo-wrapper">
            <svg :id="`svg_${bgId}`" class="combo" view-box="0 0 100 30" style="width: 100%; height: 3rem; filter: drop-shadow(0 0 1rem rgba(0, 0, 0, 0.5));" :style="`filter: drop-shadow(0 0 1rem rgba(0, 0, 0, 0.5)) drop-shadow(0 0 0.5rem ${realtimeScoreCombo >= 25 ? 'rgba(210, 110, 0, ' : 'rgba(255, 255, 0, '}${creep}));`" preserveAspectRatio="xMinYMid meet">
              <defs>
                <linearGradient :id="`grad_${bgId}`" :x1="'0%'" :y1="'0%'" :x2="'0%'" :y2="'100%'">
                  <stop offset="50%" stop-color="var(--bng-ter-yellow-100)" />
                  <stop offset="51%" :stop-color="realtimeScoreCombo >= 25 ? '#ff8400' : '#fff'" />
                  <stop offset="75%" :stop-color="realtimeScoreCombo >= 25 ? '#ff8400' : '#fff'" />
                </linearGradient>
                <mask :id="`mask_${bgId}`">
                  <text class="multiplier" x="0" y="15.5" fill="#fff" dominant-baseline="hanging" text-anchor="start"
                        :style="{ fontSize: '1.9rem' }">
                    ×{{ parseFloat(realtimeScoreCombo).toFixed(1) }}
                  </text>
                </mask>
              </defs>
              <g :mask="`url(#mask_${bgId})`">
                <rect width="100%" height="4.2rem" x="0" y="15.5" :fill="`url(#grad_${bgId})`" class="animated-rect" :style="`fill: url(#grad_${bgId}); transform: translateY(${-creep * 2}rem);`" />
              </g>
            </svg>
          </div>
        </div>
      </template>
    </div>
    <div class="remaining-time">
      <div class="wrapper">
        <div class="bar" :style="barStyle"></div>
      </div>
    </div>

    <div class="drift-bar">
      <div class="drift-scale">
        <div class="drift-progress-bar">
          <div class="progress-fill" :style="{
            left: '50%',
            width: `${Math.abs(calculatePosition(realtimeAngle, thresholds, positions)) / 2}%`,
            transform: realtimeAngle > 0 ? 'translateX(0)' : 'translateX(-100%)',
            opacity: Math.abs(realtimeAngle) < 7 ? '0.65' : '1'
          }"></div>
        </div>
        <div class="value-marks">
          <div v-for="(threshold, index) in thresholds" class="line" :key="index" :style="{
            position: 'absolute',
            left: `${(positions[index] + 100) / 2}%`,
            width: '0.125rem',
            height: '0.24rem',
            transform: threshold === 0 ? 'translateX(-50%)' : threshold > 0 ? 'translateX(-100%)' : 'translateX(0%)',
            backgroundColor: 'white'
          }"></div>
        </div>
      </div>
      <div class="drift-labels">
        <span v-for="(threshold, index) in thresholds" :key="index" :style="{
          position: 'absolute',
          left: `${(positions[index] + 100) / 2}%`,
          transform: 'translateX(-50%)',
          textAlign: 'center'
        }">
          {{ threshold === 0 ? `${Math.abs(Math.round(realtimeAngle))}°` : `${Math.abs(threshold)}°` }}
        </span>
      </div>
      <BngFlashMessage message-source="DriftFlashMessage"/>
    </div>
  </div>

</template>

<script setup>
import { useEvents } from '@/services/events'
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { icons } from "@/common/components/base"
import { uniqueId } from "@/services/uniqueId"
import { BngFlashMessage } from '@/common/components/appsUtilities'
import { useBridge } from "@/bridge"

const { lua } = useBridge()

const bgId = uniqueId("", "_")

const events = useEvents()

const realtimeScorePoints = ref(0)
const realtimeScoreCombo = ref(0)
const creep = ref(0)
const remainingComboTime = ref(0)

const centerMessage = ref(null)
const centerIcon = ref(null)
const centerFailMessage = ref(null)

const zoneName = ref(null)
const type = ref(null)
const score = ref(null)
const icon = ref(null)

const scoreToAdd = ref(0)
let countdownTimer = null
let countdownStartTime = null
let delayTimer = null // to track the 1-second delay after countdown
let startTimer = null
let centerMessageTimer = null
let remainingTimer = null

let bonusDisplayAdd = null
let bonusDisplayDispose = null
let isBonusDisplayAddActive = false

const bonusQueue = ref([])
const bonusDisplay = ref([])

const realtimeAngle = ref(0)

const steppedPerformanceFactor = ref(1)
const isCenterMessageFading = ref(false)
const isFailActive = ref(false)
const isFailAnimating = ref(false)

let failAnimationStartTime = null
let failAnimationTimer = null
const failAnimationProgress = ref(1)

const FAIL_ANIMATION_DURATION = 900 // milliseconds

const currentModifier = ref(null)
const isModifierFading = ref(false)
let modifierTimer = null

onMounted(() => {
  lua.gameplay_drift_general.onMainUIAppMounted()


  events.on('setDriftRealtimeScore', (points, combo) => {
    realtimeScorePoints.value = points
    realtimeScoreCombo.value = combo
    centerMessage.value = null
  })
  events.on('setDriftRemainingComboTime', (val) => {
    remainingComboTime.value = val
  })
  events.on('setDriftRealtimeCreep', (val) => {
    creep.value = val
  })
  events.on('setDriftRealtimeFail', (reason, icon) => {
    cancelTimers()
    isFailActive.value = true
    isFailAnimating.value = true
    isCenterMessageFading.value = false
    centerFailMessage.value = reason
    centerIcon.value = icon ? icon : ''
    bonusDisplay.value = []
    creep.value = 0

    // Store the current combo time
    const initialComboTime = remainingComboTime.value
    failAnimationProgress.value = 1

    // Animate the timer bar
    failAnimationStartTime = performance.now()
    const animateFailBar = (timestamp) => {
      const elapsed = timestamp - failAnimationStartTime
      const progress = Math.max(0, 1 - (elapsed / FAIL_ANIMATION_DURATION))
      failAnimationProgress.value = progress
      remainingComboTime.value = initialComboTime * progress

      if (progress > 0) {
        failAnimationTimer = requestAnimationFrame(animateFailBar)
      }
    }
    failAnimationTimer = requestAnimationFrame(animateFailBar)

    // Clear any existing timeout
    if (centerMessageTimer) clearTimeout(centerMessageTimer)
    // Reset fail overlay and animation state after animation
    setTimeout(() => {
      isFailActive.value = false
      isFailAnimating.value = false
      remainingComboTime.value = 0
      if (failAnimationTimer) {
        cancelAnimationFrame(failAnimationTimer)
        failAnimationTimer = null
      }
    }, FAIL_ANIMATION_DURATION)
    // First set the fading class
    centerMessageTimer = setTimeout(() => {
      isCenterMessageFading.value = true
    }, 1000)
    // Then clear the message after animation completes
    setTimeout(() => {
      centerFailMessage.value = null
      centerIcon.value = null
      isCenterMessageFading.value = false
    }, 1500)
  })
  events.on('setDriftPersistentDriftScored', (final, score, combo) => {
    centerMessage.value = "+ "
    scoreToAdd.value = final
    bonusDisplay.value = []
    startCountdown()
  })

  events.on('setDriftRealtimeAngle', (angle) => {
    realtimeAngle.value = -angle
  })

  bonusDisplayAdd = setInterval(() => {
    if (bonusQueue.value.length > 0) {
      bonusDisplay.value.push(bonusQueue.value.shift())
    }
  }, 500)
  bonusDisplayDispose = setInterval(() => {
    if (bonusDisplay.value.length > 0) {
      bonusDisplay.value.shift()
    }
  }, 10000)


  events.on('displayDriftScoreModifier', (msg) => {
    // Clear any existing timer
    if (modifierTimer) {
      clearTimeout(modifierTimer)
    }
    isModifierFading.value = false
    currentModifier.value = msg

    // Start fade out after 1.5s
    modifierTimer = setTimeout(() => {
      isModifierFading.value = true
      // Clear message after animation completes
      setTimeout(() => {
        currentModifier.value = null
        isModifierFading.value = false
      }, 500) // 500ms for fade out animation
    }, 1500)
  })

  events.on('setDriftPerformanceFactor', (factor) => {
    steppedPerformanceFactor.value = factor
  })
})

onUnmounted(() => {
  lua.gameplay_drift_general.onMainUIAppUnmounted()

  cancelTimers()
  if (centerMessageTimer) clearTimeout(centerMessageTimer)
  clearInterval(bonusDisplayAdd)
  clearInterval(bonusDisplayDispose)


  if (failAnimationTimer) {
    cancelAnimationFrame(failAnimationTimer)
  }

  if (modifierTimer) clearTimeout(modifierTimer)
})


// COMBO TIME
const barStyle = computed(() => ({
  left: `${(1-remainingComboTime.value) * 50}%`,
  right: `${(1-remainingComboTime.value) * 50}%`,
  display: remainingComboTime <= 10 ? 'hidden' : 'auto',
  background: isFailAnimating.value
    ? 'linear-gradient(0deg, #F00 0%, #F00 0.25rem, rgba(255, 0, 0, 0.25) 0.251rem, rgba(255, 0, 0, 0) 1rem)'
    : steppedPerformanceFactor.value >= 4
      ? 'linear-gradient(0deg, #1E8C1E 0%, #1E8C1E 0.25rem, rgba(30, 140, 30, 0.25) 0.251rem, rgba(30, 140, 30, 0) 1rem)'
      : 'linear-gradient(0deg, #F60 0%, #F60 0.25rem, rgba(255, 102, 0, 0.25) 0.251rem, rgba(255, 102, 0, 0) 1rem)'
}))


function cancelTimers() {
  if (countdownTimer) {
    cancelAnimationFrame(countdownTimer)
    countdownTimer = null
  }
  if (delayTimer) {
    clearTimeout(delayTimer)
    delayTimer = null
  }
  if (startTimer) {
    clearTimeout(startTimer)
    startTimer = null
  }
  if (failAnimationTimer) {
    cancelAnimationFrame(failAnimationTimer)
    failAnimationTimer = null
  }
}

function startCountdown() {
  // Cancel any existing timers before starting a new countdown
  cancelTimers()

  startTimer = setTimeout(() => {
    const initialScore = scoreToAdd.value
    const scoreDwindleAnimDuration = 1000

    function countdown(timestamp) {
      if (!countdownStartTime) countdownStartTime = timestamp
      const elapsedTime = timestamp - countdownStartTime

      if (elapsedTime >= scoreDwindleAnimDuration) {
        scoreToAdd.value = 0
        countdownStartTime = null

        // After countdown completes, wait for 1 second to set scoreToAdd to -1 and clear centerMessage
        delayTimer = setTimeout(() => {
          scoreToAdd.value = -1
          centerMessage.value = null
          realtimeScorePoints.value = 0
          realtimeScoreCombo.value = 0
          creep.value = 0
          delayTimer = null // clear the delay timer after it's used
        }, 1000) // wait for 1 second
      } else {
        scoreToAdd.value = Math.floor(initialScore * (1 - elapsedTime / scoreDwindleAnimDuration))
        countdownTimer = requestAnimationFrame(countdown)
      }
    }

    countdownTimer = requestAnimationFrame(countdown)
  }, 1250) // delay by 1.25s
}

// Threshold angles in degrees, defining key positions along the gauge
const thresholds = [-110, -60, -20, 0, 20, 60, 110];

// Corresponding positions on the gauge from -100% to 100%
const positions = [-100, -70, -35, 0, 35, 70, 100];

// Single interpolation function to map the input angle to the gauge position
const calculatePosition = (y, thresholds, positions) => {
  // Clamp input value within the bounds of the thresholds
  const clampedY = Math.max(thresholds[0], Math.min(thresholds[thresholds.length - 1], y));

  // Iterate through the threshold intervals to find the current segment
  for (let i = 0; i < thresholds.length - 1; i++) {
    if (clampedY >= thresholds[i] && clampedY <= thresholds[i + 1]) {
      // Linear interpolation within the current segment
      const t = (clampedY - thresholds[i]) / (thresholds[i + 1] - thresholds[i]);
      return positions[i] + t * (positions[i + 1] - positions[i]);
    }
  }

  // Return center position if something goes wrong (fallback)
  return 0;
}

</script>

<style scoped lang="scss">
$FAIL_ANIMATION_DURATION: 900;

.main-container{
  color: white;
  margin: 0 15rem;
  font-size: 1rem;
  font-family: Overpass-mono, var(--fnt-defs);
  display: flex;
  flex-direction:column;
  height: 100%;
  .cached-score-wrapper {
    $score-z-index: 2;
    $z-index-step: 2;
    position: relative;

    .performance-background {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      transform-origin: bottom;
      transition: transform 0.3s ease;
      z-index: -1;
    }

    font-size: 2.5rem;
    display: grid;
    gap: 0.5rem;
    grid-template-columns: 1fr auto 1fr;
    justify-content: center;
    align-content: stretch;
    align-items: center;

    font-style: italic;
    flex: 0 0 auto;

    z-index: z-index-offset(1);

    .center {
      font-weight: 900;
      letter-spacing: -0.05rem;
      text-shadow: rgb(255, 255, 255) 0 0 2px, rgba(0, 0, 0, 0.4) 0 0 2rem;
      grid-column: 1/-1;
      text-align: center;
      z-index: z-index-offset(4);
      transition: transform 0.5s ease, opacity 0.5s ease;

      &.fade-out {
        transform: translateY(2rem);
        opacity: 0;
      }
    }

    .cached-score {
      grid-column: 2 / 2;
      text-align: center;
      font-weight: 800;
      text-shadow: rgb(255, 255, 255) 0 0 1px, rgba(0, 0, 0, 0.4) 0 0 2rem;
      z-index: z-index-offset(4);
      display: flex;
      flex-direction: row;
      align-items: center;
      gap: 1rem;

      .score-container {
        position: relative;
        display: flex;
        align-items: center;
        justify-content: center;

        .score-modifier {
          position: absolute;
          left: -1rem;
          transform: translateX(-100%);
          font-size: 1rem;
          font-weight: 400;
          white-space: nowrap;
          opacity: 1;
          animation: popIn 0.1s ease-out;
          transition: opacity 0.3s ease, transform 0.3s ease;

          &.fade-out {
            opacity: 0;
            transform: translateX(10%);
          }
        }
      }

      .score {
        font-size: 2.7rem;
        line-height: 2.7rem;
        margin-left: 1rem;
      }

      .combo-wrapper {
        width: 5rem;
      }
    }
    .combo {
      flex: 0 0 6.5rem;
      position:relative;
      z-index: 0;
      text-shadow: rgb(255, 255, 255) 0 0 1px, rgba(0, 0, 0, 0.4) 0 0 2rem;
      justify-self: start;

      font-size: 1.85rem;
      line-height: 2rem;
      font-weight: 700;

      z-index: z-index-offset(4);

      max-height: 100%;

      svg text.multiplier {
        font-size: 2rem;
      }

      .text {
        z-index: 1000;
      }
    }
    .added-score {
      position: relative;
      grid-column: 1 / 1;

      .score-item {
        position: absolute;
        top: 0;
        bottom: 0;
        right: 0;
        opacity: 0;
        // opacity: 1;
        display: flex;
        justify-content: flex-end;
        align-items: center;
        font-size: 2rem;
        font-weight: 800;
        padding-right: 0.25rem;
        transform-origin: 50% 50%;

        animation:
          500ms linear drift-opaque-delay,
          1000ms cubic-bezier(0.355, 0.060, 0.035, 1.000) 500ms drift-fade-out,
          1500ms cubic-bezier(0.355, 0.060, 0.035, 1.000) drift-move-scale;
      }
    }
    .fail-overlay {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: linear-gradient(0deg,
        rgba(255, 0, 0, 0.5) 0%,
        rgba(255, 0, 0, 0.3) 50%,
        rgba(255, 0, 0, 0) 100%
      );
      opacity: 0;
      pointer-events: none;
      z-index: -1;
      transform-origin: bottom;
      transform: scaleY(0);

      &.active {
        animation: fail-animation #{$FAIL_ANIMATION_DURATION}ms ease-in forwards;
      }
    }
  }
  .remaining-time {
    flex: 0 0 0.25rem;
    display: flex;
    align-items:center;
    .wrapper {
      width: 100%;
      background-color: rgba(255, 255, 255, 0.5);
      position: relative;
      height: 0.25rem;

      .bar {
        background: linear-gradient(0deg, #F60 0%, #F60 0.25rem, rgba(255, 102, 0, 0.25) 0.251rem, rgba(255, 102, 0, 0) 1rem);
        position: absolute;
        width: auto;
        left: 50%;
        right: 50%;
        top: -1rem;
        bottom: 0;
        z-index: z-index-offset(2);
      }
    }
  }
  .drift-bar {
    position: relative;
    flex: 0 0 1rem;
    display: flex;
    flex-flow: column;
    margin-top: 0.25rem;
    .drift-scale {
      position: relative;
      border-top: 0.125rem solid rgba(white, 0.6);
      box-sizing: border-box;
      flex: 0 0 1.25rem;
      .value-marks {
        position: relative;
        width: 100%;
        height: 1rem;
        .line {
          position: absolute;
          width: 0.125rem;
          height: 0.24rem;
          background-color: rgba(white, 0.6);
        }
      }
    }
    .drift-labels {
      position: relative;
      flex: 0 0 1.25rem;
      color: white;
      margin-top: -1rem;

      span {
        &:nth-child(4) { // Center value (realtime angle)
          font-size: 1.4rem;
          font-weight: 800;
        }
      }
    }
  }
}


@keyframes drift-opaque-delay {
  0% {
    opacity: 0.8;
  }
  100% {
    opacity: 0.8;
  }
}

@keyframes drift-move-scale {
  0% {
    transform: translateY(0) scale(1);
  }
  100% {
    transform: translateY(20px) scale(0.6);
  }
}

@keyframes drift-fade-out {
  0% {
    opacity: 0.8;
  }
  15% {
    opacity: 0.6;
  }
  100% {
    opacity: 0;
  }
}

@keyframes fail-animation {
  0% {
    opacity: 1;
    transform: scaleY(1);
  }
  100% {
    opacity: 0;
    transform: scaleY(0);
  }
}

@keyframes popIn {
  0% {
    font-size: 1.3rem;
  }
  100% {
    font-size: 1rem;
  }
}

.drift-progress-bar {
  position: absolute;
  top: 0rem;
  left: 0;
  width: 100%;
  height: 0.25rem;
  overflow: hidden;

  .progress-fill {
    position: absolute;
    height: 100%;
    background-color: white;
  }
}

</style>