<template>
  <BngPopoverContent
    ref="popoverContent"
    :name="name"
    :offset="offset"
    :hide-arrow="hideArrow"
    @placementChanged="relay.placementChanged"
    @hide="hide">
    <div ref="popoverMenu" class="bng-popover-menu">
      <slot></slot>
    </div>
  </BngPopoverContent>
</template>

<script setup>
import { ref, watch, watchEffect, nextTick } from "vue"
import { BngPopoverContent } from "@/common/components/base"
