const popover = usePopover()

defineOptions({ inheritAttrs: false })

const props = defineProps({
  /// relayed props (same as in BngPopoverContent)
  name: String,
  offset: {
    type: Number,
    default: 4,
  },
  hideArrow: Boolean,
  /// menu props
  focus: Boolean,
})

const emit = defineEmits(["show", "hide", "placementChanged"])

const relay = {
  // show: (...args) => {
  //   scopeControl.set("bng-popover-menu")
  //   emit("show", ...args)
  // },
  // hide: (...args) => {
  //   scopeControl.set(scopeControl.oldScope)
  //   emit("hide", ...args)
