  //   return () => this.unwatch(callback)
  // }

  // /**
  //  * Unwatch
  //  * @param {function} callback Callback that was registered before
  //  */
  // unwatch(callback) {
  //   if (callback in this._watchers) {
  //     for (const unwatch of this._watchers[callback])
  //       unwatch()
  //     delete this._watchers[callback]
