<template>
  <LayoutSingle
    v-bng-scoped-nav="{ activated: scopedNavState.rootActivated, noPartial: true }"
    class="vehcfg layout-content-full layout-align-hstart"
    v-bng-on-ui-nav:tab_l="broadcastEvent"
    v-bng-on-ui-nav:tab_r="broadcastEvent"
    @activate="scopeChanged(true, $event)"
    @deactivate="scopeChanged(false, $event)">
    <!--
    <div class="vehconfig-new-ui" v-bng-blur="true" @click="backToOld()" bng-nav-item>
      {{ $t("ui.vehicleconfig.gotoold") }}
    </div>
    -->

    <Tabs class="bng-tabs" v-bng-frustum-mover.left="true" @change="syncWithStates">
      <TabList v-bng-blur />
      <Parts :tab-selected="tab === 'parts'" :tab-heading="$t('ui.vehicleconfig.parts')" v-bng-blur />
      <Tuning :tab-selected="tab === 'tuning'" :tab-heading="$t('ui.vehicleconfig.tuning')" v-bng-blur @mirrors:click="toMirrors" />
      <Paint :tab-selected="tab === 'color'" :tab-heading="$t('ui.vehicleconfig.color')" v-bng-blur />
      <Save :tab-selected="tab === 'save'" :tab-heading="$t('ui.vehicleconfig.save') + ' & ' + $t('ui.vehicleconfig.load')" v-bng-blur />
      <Debug :tab-selected="tab === 'debug'" :tab-heading="$tt('ui.debug.vehicle')" v-bng-blur />
    </Tabs>
  </LayoutSingle>
</template>

<script setup>
import { onMounted, reactive } from "vue"
import { LayoutSingle } from "@/common/layouts"
import { Tabs, TabList } from "@/common/components/utility"
import { vBngScopedNav, vBngBlur, vBngFrustumMover, vBngOnUiNav } from "@/common/directives"
import { handleUINavEvent as sendToCrossfire } from "@/services/crossfire"

import Parts from "../components/Parts.vue"
import Tuning from "../components/Tuning.vue"
import Paint from "../components/Paint.vue"
import Save from "../components/Save.vue"
import Debug from "../components/Debug.vue"

// import { useUINavScope } from "@/services/uiNav"
// useUINavScope("vehicle-config")
const mirrorsRoute = "menu.vehicleconfig.tuning.mirrors"

const props = defineProps({
  tab: {
    type: String,
    default: "parts",
    validator: val => !val || ["parts", "tuning", "color", "save", "debug"].includes(val),
  },
})

const scopedNavState = reactive({
  rootActivated: false,
  tabTriggered: false,
  ignoreReroute: false,
})

const scopeChanged = (activated, event) => {
  scopedNavState.rootActivated = activated
  const detail = event.detail
  if (detail && detail.args && detail.args.isUnmount) return
  if (!activated && !scopedNavState.tabTriggered && !scopedNavState.ignoreReroute) window.bngVue.gotoAngularState("menu.mainmenu")
}

const toMirrors = () => {
  scopedNavState.ignoreReroute = true
  window.bngVue.gotoGameState(mirrorsRoute)
}

onMounted(() => {
  scopedNavState.rootActivated = true
})

function syncWithStates(tab) {
  if (!window.bngVue) return
  tab = ["parts", "tuning", "color", "save", "debug"][tab.index] || "parts"
  window.bngVue.gotoAngularState(`menu.vehicleconfig.${tab}`)
}

function broadcastEvent(event) {
  scopedNavState.tabTriggered = true
  // TODO: This is a hack. Update scoped nav to allow specifying of uinav events to allow to bubble up
  sendToCrossfire(event)
}

const backToOld = () => window.bngVue && window.bngVue.gotoAngularState(`menu.vehicleconfigold.${props.tab}`)
</script>

<style lang="scss" scoped>
.vehcfg {
  padding-top: 2.5em;
  padding-bottom: 2.75em;
  pointer-events: none;
  > * {
    pointer-events: all;
  }
}
:deep(.bng-tabs) {
  --tab-bg-active: var(--bng-cool-gray-700);
  --tab-bg-hover: var(--bng-orange-700);
  // --tab-bg: rgba(0,0,0,0.9);
  // --tab-content-bg: rgba(0,0,0,0.9);
  --tab-bg: rgba(var(--bng-cool-gray-900-rgb), 0.95);
  --tab-content-bg: rgba(var(--bng-cool-gray-900-rgb), 0.95);
  width: 35em;
  .tab-item {
    white-space: nowrap;
    // &:not(.tab-active-tab) {
    flex: 1 auto;
    text-overflow: ellipsis;
    overflow: visible;
    // }
  }
  .tab-list {
    margin: 0;
  }
  .tab-list,
  .tab-content {
    border-radius: 0;
  }
}

.vehconfig-new-ui {
  position: absolute;
  display: inline-block;
  top: 2.9em;
  left: 35.35em;
  width: auto;
  height: auto;
  padding: 0.75em 1em;
  border-radius: var(--bng-corners-1);
  text-align: center;
  background-color: rgba(0, 0, 0, 0.5);
  font-weight: 600;
  color: #fff;
}
.vehconfig-new-ui:hover,
.vehconfig-new-ui:focus {
  background-color: rgba(0, 0, 0, 0.7);
}
</style>
